import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as a,c as s,o as n,ag as r}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/analytics-overview.png",l="/docs/screenshots/analytics-section.png",c="/docs/icons/info.svg",h="/docs/screenshots/analytics-info-modal.png",d="/docs/screenshots/analytics-heatmap.png",p="/docs/screenshots/analytics-category.png",o="/docs/icons/plus.svg",u="/docs/screenshots/analytics-filters.png",g="/docs/screenshots/analytics-phenotypes-view.png",m="/docs/screenshots/analytics-phenotypes.png",y="/docs/icons/copy.svg",b="/docs/screenshots/analytics-phenotype-drag.png",f="/docs/screenshots/analytics-category-from-column.png",v="/docs/screenshots/analytics-category-from-phenotypes.png",w="/docs/screenshots/analytics-legend.png",A=JSON.parse('{"title":"Analytics & Phenotyping","description":"Load per-object measurement CSVs to color segmentation labels by column (heatmap or category), filter objects by value, and build named phenotype populations with composable filter conditions.","frontmatter":{"title":"Analytics & Phenotyping","description":"Load per-object measurement CSVs to color segmentation labels by column (heatmap or category), filter objects by value, and build named phenotype populations with composable filter conditions."},"headers":[],"relativePath":"guides/analytics-phenotyping.md","filePath":"guides/analytics-phenotyping.md"}'),x={name:"guides/analytics-phenotyping.md"};function k(q,e,P,_,T,C){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="analytics-phenotyping" tabindex="-1">Analytics &amp; Phenotyping <a class="header-anchor" href="#analytics-phenotyping" aria-label="Permalink to &quot;Analytics &amp; Phenotyping&quot;">​</a></h1><p>Load per-object measurements from a CSV, color your segmentation by any column, filter objects by range or value, and build named <strong>phenotype</strong> groups to classify cell populations.</p><p>The short version: analytics lives <strong>inside a label</strong>. You load a table that maps object ID → measurements, and the viewer colors the label mask by any column. Everything you configure is per-label. Different labels can have different CSVs, different coloring, different phenotypes.</p><p><img src="'+i+'" alt="Nuclei coloured by the phenotype_class column, with a legend in the bottom-right of the image and the Labels tab open on the Analytics section" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A segmentation label loaded on the image (either embedded in the OME-Zarr or added via <strong>Add Local</strong> / <strong>Add URL</strong>).</li><li>A table of per-object measurements whose object-ID column matches the label&#39;s pixel values. Most CellProfiler, FIJI and QuPath exports work as they come. See the <a href="./analytics-format.html">Analytics Data Format</a> for the full contract, and for hosting a whole analysis (masks included) behind one URL.</li><li>Any browser, if you load from a URL. Picking a <strong>file from disk</strong> needs the File System Access API, which today means Chrome or Edge.</li></ul><h2 id="loading-a-csv" tabindex="-1">Loading a CSV <a class="header-anchor" href="#loading-a-csv" aria-label="Permalink to &quot;Loading a CSV&quot;">​</a></h2><ol><li>Open the <strong>Labels</strong> tab and click a label row to expand its detail panel.</li><li>Inside the expanded detail, find the <strong>ANALYTICS</strong> section.</li><li>Click <strong>Load analytics file</strong> to pick a CSV or Parquet from disk, or <strong>Load from URL…</strong> to paste an address. Once something is loaded, <strong>Replace</strong> swaps it.</li><li>The viewer parses it, profiles every column, and shows a summary: <code>filename · N obj · M col</code>.</li></ol><p>You never pick a format. Whichever way you came in, the viewer reads it off what you gave it: <code>.parquet</code> as Parquet, a trailing slash as an analysis directory, anything else as a delimited table. A directory is how one address brings masks and measurements together, and there is a shortcut for it: <strong>Add URL</strong> in the Labels toolbar attaches the masks and their analytics in one action, without expanding a label first.</p><p><img src="'+l+'" alt="The ANALYTICS section header + summary &#39;nuclei · 18648 obj · 37 col&#39; with Replace / Clear buttons, and the FILTERS / PHENOTYPES stubs below" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="object-id-auto-detection" tabindex="-1">Object-ID auto-detection <a class="header-anchor" href="#object-id-auto-detection" aria-label="Permalink to &quot;Object-ID auto-detection&quot;">​</a></h3><p>The viewer recognises the usual spellings of an object-ID column. One match and it uses it, several and it asks which, none and it falls back to row index, which matches the CellProfiler, FIJI and QuPath default exports. The <a href="./analytics-format.html#step-1-the-smallest-thing-that-works-a-csv">recognised names are listed in the format guide</a>, along with why that column decides whether anything lines up at all.</p><h3 id="inspecting-the-columns" tabindex="-1">Inspecting the columns <a class="header-anchor" href="#inspecting-the-columns" aria-label="Permalink to &quot;Inspecting the columns&quot;">​</a></h3><p>Click the <img src="'+c+'" class="fn-icon" alt="info"> info button next to the filename to open a table summary:</p><ul><li><strong>Numeric columns</strong>: min, max, mean, standard deviation, null count</li><li><strong>String columns</strong>: number of unique values (capped at 500)</li><li>Detected object-ID column is flagged at the top.</li></ul><p><img src="'+h+'" alt="TableInfoModal showing the column list with types and statistics" style="max-width:560px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><div class="tip custom-block"><p class="custom-block-title">File formats</p><p>CSV is the common path. Tab- and semicolon-delimited tables work too, and the parser detects the separator itself. Parquet is read column by column, so it stays usable at plate scale. <a href="./analytics-format.html#step-2-when-the-table-gets-big-parquet">When the table gets big</a> covers the trade-off.</p></div><h2 id="color-by-column" tabindex="-1">Color by column <a class="header-anchor" href="#color-by-column" aria-label="Permalink to &quot;Color by column&quot;">​</a></h2><p>With analytics loaded, open the label&#39;s <strong>color swatch popover</strong> (the coloured square on the label row). Three coloring modes become available:</p><ul><li><strong>Solid</strong>: one color for everything (default, no analytics needed)</li><li><strong>Random</strong>: hash object ID → color (no analytics needed)</li><li><strong>Heatmap</strong>: numeric column → color ramp</li><li><strong>Category</strong>: string column → distinct color per value</li></ul><h3 id="heatmap-numeric-columns" tabindex="-1">Heatmap (numeric columns) <a class="header-anchor" href="#heatmap-numeric-columns" aria-label="Permalink to &quot;Heatmap (numeric columns)&quot;">​</a></h3><p>Pick a numeric column from the dropdown. The viewer colors every object on the canvas by its value along a scientific color ramp.</p><p>Available ramps:</p><ul><li><strong>viridis</strong>: perceptually uniform, default, handles most data</li><li><strong>magma</strong>, <strong>inferno</strong>, <strong>plasma</strong>: darker low, brighter high</li><li><strong>coolwarm</strong>: diverging, useful for zero-centered measurements</li><li><strong>turbo</strong>: high-contrast rainbow</li></ul><p><img src="'+d+'" alt="Nuclei coloured by an area_um2 heatmap, with the colour popover open showing the Heatmap tab, the column, the viridis ramp and the scale histogram, and the ramp legend on the image" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Below the column and ramp controls, a histogram of the column&#39;s values appears with a dual-range slider. Drag the handles to <strong>override the display min/max</strong>. Useful when a handful of outliers compress the interesting signal. The legend card reflects your override in real time.</p><h3 id="category-string-columns" tabindex="-1">Category (string columns) <a class="header-anchor" href="#category-string-columns" aria-label="Permalink to &quot;Category (string columns)&quot;">​</a></h3><p>Pick a string column. Each unique value gets a distinct color from a deterministic palette (same value → same color across reloads). The canvas re-colors every object by its category, and a legend card below the scale bar lists color ■ value pairs.</p><p>The screenshot below uses a column called <code>phenotype_class</code>, written by the segmentation run that produced the labels. It holds one value per object: <code>positive</code>, <code>negative</code> or <code>excluded</code>. Nothing about it is special to the viewer. It is a string column like any other, and it is <strong>not</strong> the same thing as the <a href="#phenotypes">Phenotypes</a> feature further down this page. See <a href="#phenotype-groups-and-class-columns">Phenotype groups and class columns</a>.</p><p><img src="'+p+'" alt="Nuclei coloured by the phenotype_class column, with the colour popover open showing the Category tab, Categories from set to that column, and its three values, plus the legend on the image" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>For columns with many unique values, the legend caps at 12 rows and shows &quot;+N more&quot;.</p><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Below the color-by section, a <strong>FILTERS</strong> panel hides objects that don&#39;t match your conditions. Filters don&#39;t change the coloring. They just remove non-matching objects from the canvas.</p><p>Click <img src="'+o+'" class="fn-icon" alt="add"> <strong>Add filter</strong> and pick a column from the popover. The filter&#39;s UI depends on the column type:</p><ul><li><strong>Numeric</strong>: histogram + dual-range slider. The range you pick is inclusive; objects outside it become invisible.</li><li><strong>String</strong>: checkbox grid of unique values, all selected by default. Uncheck the values you want to exclude.</li></ul><p>Multiple filters <strong>compose with AND</strong>: an object must pass every active filter to stay visible. Each filter row has a remove control and a collapse control to hide its histogram when you want a compact view.</p><p><img src="'+u+'" alt="FILTERS section with two filter rows: area_um2 with a histogram and dual-range slider, phenotype_class with value chips" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><div class="tip custom-block"><p class="custom-block-title">Filters are independent of coloring</p><p>You can color by <code>area_px</code> (heatmap) while filtering by <code>is_mitotic</code> (string). The two settings compose cleanly. Color reflects the data dimension you care about; filters remove the objects you don&#39;t.</p></div><h2 id="phenotypes" tabindex="-1">Phenotypes <a class="header-anchor" href="#phenotypes" aria-label="Permalink to &quot;Phenotypes&quot;">​</a></h2><p><img src="'+g+'" alt="The viewer with nuclei coloured by two phenotype groups, Small in blue and Large in orange. The colour popover shows Categories from set to Phenotypes, the legend on the image lists both groups, and the sidebar shows the groups with their filters and match counts" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Two groups, <code>Small</code> and <code>Large</code>, split on nuclear perimeter. The colours on the image, the legend, the source dropdown and the group list all show the same two groups.</p><p>A <strong>phenotype</strong> is a named, coloured group of filter conditions. Think of it as a named bucket: &quot;Small cells with high marker X&quot;, &quot;Cells at the tumor-stroma boundary&quot;, &quot;Cells that entered mitosis.&quot; Phenotypes compose on top of the same filter machinery above, but each phenotype has its own color, name, and visibility.</p><p>When at least one phenotype exists, the canvas switches to <strong>phenotype coloring</strong>: every object gets the color of the first phenotype it matches. Objects that match nothing show in gray (toggleable) or hide entirely.</p><p><img src="'+m+'" alt="The PHENOTYPES section with two groups. The first is open, showing the perimeter filter it is built from as a histogram with a range slider, and the number of objects it matches" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="creating-a-phenotype" tabindex="-1">Creating a phenotype <a class="header-anchor" href="#creating-a-phenotype" aria-label="Permalink to &quot;Creating a phenotype&quot;">​</a></h3><p>Click <img src="'+o+'" class="fn-icon" alt="add"> <strong>Add phenotype</strong>. A new group appears with a default color, name, and no filters. Click the name to rename it. Click the swatch to pick a colour. Add filters inside the group the same way you add global filters. The difference: they belong to this group alone.</p><p>The first phenotype you create <strong>auto-flips</strong> the label&#39;s coloring to phenotype mode. You don&#39;t need to manually switch. The viewer assumes &quot;you just created a phenotype, you probably want to see it.&quot;</p><h3 id="reordering-first-match-wins" tabindex="-1">Reordering (first-match-wins) <a class="header-anchor" href="#reordering-first-match-wins" aria-label="Permalink to &quot;Reordering (first-match-wins)&quot;">​</a></h3><p>Phenotype groups evaluate <strong>top to bottom</strong>. The first group an object matches wins the color. If you have overlapping definitions, the order of groups matters.</p><p>Drag the grip handle on the left of each phenotype to reorder. Duplicate a group with the <img src="'+y+'" class="fn-icon" alt="duplicate"> copy icon if you need a similar one with slight tweaks. Filters and color copy over; the name gets &quot;(copy)&quot; appended.</p><p><img src="'+b+'" alt="Phenotype row mid-drag, showing the grip handle and the drop target indicator" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="show-unmatched-objects" tabindex="-1">Show unmatched objects <a class="header-anchor" href="#show-unmatched-objects" aria-label="Permalink to &quot;Show unmatched objects&quot;">​</a></h3><p>A checkbox below the phenotype list: <strong>Show unmatched objects (gray)</strong>. Objects that match no phenotype either:</p><ul><li>Render in gray (checkbox on): useful to see the full context</li><li>Hide entirely (checkbox off): useful to focus only on classified cells</li></ul><h3 id="assigned-vs-palette-colors" tabindex="-1">Assigned vs palette colors <a class="header-anchor" href="#assigned-vs-palette-colors" aria-label="Permalink to &quot;Assigned vs palette colors&quot;">​</a></h3><p>A <strong>Colors</strong> toggle switches between two coloring schemes:</p><ul><li><strong>Assigned</strong>: every phenotype uses its own custom color, the one you picked on its swatch.</li><li><strong>Palette</strong>: colors come from the built-in Tableau10 categorical palette, by position in the list. Reordering changes the colors.</li></ul><p>Use <strong>Palette</strong> when you&#39;re drafting and want colors to come for free; switch to <strong>Assigned</strong> when you&#39;ve finalized your palette and want every group to keep a specific hue across sessions.</p><h3 id="phenotype-groups-and-class-columns" tabindex="-1">Phenotype groups and class columns <a class="header-anchor" href="#phenotype-groups-and-class-columns" aria-label="Permalink to &quot;Phenotype groups and class columns&quot;">​</a></h3><p>Your data may already carry a class column, written by whatever produced the labels. The screenshots in <a href="#category-string-columns">Category</a> use one called <code>phenotype_class</code>, holding <code>positive</code>, <code>negative</code> or <code>excluded</code> per object. That column is not the same thing as the groups you build here, even though both end up in the same place: the <strong>Categories from</strong> dropdown, in <strong>Category</strong> mode.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px;margin:1rem 0;"><figure style="margin:0;"><img src="'+f+'" alt="The colour popover in Category mode with Categories from set to phenotype_class, listing the values negative, positive and excluded" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">A column from your data</figcaption></figure><figure style="margin:0;"><img src="'+v+'" alt="The same popover with Categories from set to Phenotypes, listing the two groups Small and Large" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:6px;"><figcaption style="font-size:.8em;color:var(--vp-c-text-2);text-align:center;padding-top:4px;">Groups you defined</figcaption></figure></div><p>Use the column when your analysis has already classified the objects. Build groups when it has not, or when you want to try a cut-off and move it. Switching between the two costs nothing, and your groups stay defined while you look at a column.</p><h2 id="the-canvas-legend" tabindex="-1">The canvas legend <a class="header-anchor" href="#the-canvas-legend" aria-label="Permalink to &quot;The canvas legend&quot;">​</a></h2><p>Whenever any color viz is active (heatmap, category, or phenotype), a legend card appears above the scale bar in the bottom-right. It&#39;s read-only. It exists so someone looking at the image understands what the colors mean.</p><p><img src="'+w+'" alt="The on-canvas legend card: the label name, the column it is coloured by, and a colour and name per category" style="max-width:240px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Multiple labels can show legends at once: one card per label, stacked. Hidden labels&#39; cards disappear automatically; toggle visibility via the <img src="'+t+'" class="fn-icon" alt="visibility"> icon on the label row to control the overlay.</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Analytics data, visualizations, filters, and phenotypes all persist to the browser&#39;s IndexedDB, keyed by the image&#39;s ZARR URL / local folder handle. Reload the page, reopen the image. Your CSV is still loaded, your heatmap is still active, your phenotypes are still in place.</p><p>The URL query string encodes channel + zoom + selection state, but <strong>not</strong> analytics data itself (CSVs can be large). The URL is enough to navigate back to your view; the local browser handles the CSV.</p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>Analytics and phenotype sections are <strong>hidden on phone-width viewports</strong>. The underlying reason: local CSV selection requires the Chrome/Edge File System Access API, which isn&#39;t available on mobile. Tablets show the full desktop UI.</p><p>URL-based analytics (the HTTPS-hosted roadmap item) will unblock phone viewing of pre-built phenotype configurations. Once shipped, mobile users will be able to receive a shared link and see the phenotype-coloured view, just without the ability to tweak the CSV.</p><h2 id="gotchas" tabindex="-1">Gotchas <a class="header-anchor" href="#gotchas" aria-label="Permalink to &quot;Gotchas&quot;">​</a></h2><p><strong>Object-ID alignment.</strong> CSVs from different tools start counting from different bases. CellProfiler&#39;s <code>ObjectNumber</code> is 1-based, QuPath&#39;s detection IDs are often hash-style, napari&#39;s <code>label_id</code> matches the underlying <code>regionprops</code> convention. If objects aren&#39;t coloring at all after load, open the info modal and check: the detected object-ID column should match your label&#39;s pixel values.</p><p><strong>String columns with &gt; 500 unique values</strong> are truncated for performance. Category coloring still works, but the legend caps at 12 rows.</p><p><strong>Mixed-type columns.</strong> If any cell parses as string, the whole column is treated as string. You can&#39;t heatmap a column that accidentally has &quot;NA&quot; sprinkled through numeric values; clean up exports or filter first.</p><p><strong>Hidden labels don&#39;t contribute a legend card.</strong> If the legend isn&#39;t appearing, check that the label is visible (<img src="'+t+'" class="fn-icon" alt="visibility"> icon on the label row). We treat hidden labels as &quot;the user doesn&#39;t want this on screen&quot; and skip the legend card accordingly.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./annotations.html">Annotations</a>: annotate regions of interest on top of the same image</li><li><a href="./sharing.html">Sharing Views</a>: URL state captures the current view for reviewer handoff</li></ul>',79)])])}const I=a(x,[["render",k]]);export{A as __pageData,I as default};
